$src = 'gelen'
$root = 'arsiv'
$exts = @('.jpg','.jpeg','.png','.mp4','.mov')

Get-ChildItem -Path $src -Recurse -File | ForEach-Object {
    $e = $_.Extension.ToLower()
    if ($exts -notcontains $e) { return }

    $n = $_.BaseName
    $dt = $null

    # Ilk YYYYMMDD (8 rakam, 20 ile baslayan)
    if ($n -match '(?<!\d)(20\d{6})(?!\d)') {
        [datetime]::TryParseExact($matches[1], 'yyyyMMdd', $null, [System.Globalization.DateTimeStyles]::None, [ref]$dt) | Out-Null
    }
    # YYYY-MM-DD
    elseif ($n -match '(?<!\d)(\d{4}-\d{2}-\d{2})(?!\d)') {
        [datetime]::TryParseExact($matches[1], 'yyyy-MM-dd', $null, [System.Globalization.DateTimeStyles]::None, [ref]$dt) | Out-Null
    }

    if ($dt) {
        $folder = Join-Path $root "$($dt.Year)" "$($dt.Month.ToString('D2'))"
    } else {
        $folder = Join-Path $root 'tarihsiz'
    }

    if (!(Test-Path $folder)) { New-Item -ItemType Directory -Path $folder -Force | Out-Null }

    $dest = Join-Path $folder $_.Name
    if (Test-Path $dest) {
        $b = $_.BaseName
        $e2 = $_.Extension
        $i = 1
        while (Test-Path (Join-Path $folder "$($b)_$i$e2")) { $i++ }
        $dest = Join-Path $folder "$($b)_$i$e2"
    }

    Move-Item -Path $_.FullName -Destination $dest
    Write-Host ("{0} -> {1}" -f $_.FullName, $dest)
}

