import os, re, shutil
from datetime import datetime

root = 'arsiv'
tarihsiz = os.path.join(root, 'tarihsiz')
exts = {'.jpg', '.jpeg', '.png', '.mp4', '.mov'}

def extract_date(name):
    base = os.path.splitext(name)[0]
    m = re.search(r'(?<!\d)(20\d{6})(?!\d)', base)
    if m:
        try: return datetime.strptime(m.group(1), '%Y%m%d')
        except ValueError: pass
    m = re.search(r'(?<!\d)(\d{4}-\d{2}-\d{2})(?!\d)', base)
    if m:
        try: return datetime.strptime(m.group(1), '%Y-%m-%d')
        except ValueError: pass
    return None

def strip_suffix1(name):
    base, ext = os.path.splitext(name)
    if base.endswith('_1'):
        return base[:-2] + ext
    return name

moved = []
for f in sorted(os.listdir(tarihsiz)):
    p = os.path.join(tarihsiz, f)
    if not os.path.isfile(p):
        continue
    ext = os.path.splitext(f)[1].lower()
    if ext not in exts:
        continue
    dt = extract_date(f)
    newname = strip_suffix1(f)
    if dt:
        folder = os.path.join(root, str(dt.year), f"{dt.month:02d}")
        os.makedirs(folder, exist_ok=True)
        dest = os.path.join(folder, newname)
        if os.path.exists(dest):
            base, e = os.path.splitext(newname)
            i = 1
            while os.path.exists(os.path.join(folder, f"{base}_{i}{e}")):
                i += 1
            dest = os.path.join(folder, f"{base}_{i}{e}")
        shutil.move(p, dest)
        moved.append((f, dest))
    else:
        dest = os.path.join(tarihsiz, newname)
        if os.path.abspath(p) != os.path.abspath(dest):
            if os.path.exists(dest):
                base, e = os.path.splitext(newname)
                i = 1
                while os.path.exists(os.path.join(tarihsiz, f"{base}_{i}{e}")):
                    i += 1
                dest = os.path.join(tarihsiz, f"{base}_{i}{e}")
            os.rename(p, dest)
            moved.append((f, dest))
        else:
            moved.append((f, '(zaten yerinde)'))

for src, dst in moved:
    print(f'{src} -> {dst}')
print('Toplam islem:', len(moved))

